export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/shift; mkdir -p $D && cd $D || exit 1
cat > /tmp/sh.b64 <<'B64EOF'

B64EOF
rm -rf ./*; base64 -d /tmp/sh.b64 > /tmp/sh.zip && unzip -oq /tmp/sh.zip -d .
for t in y24_base y24_val y25_base y25_val y26_base y26_val; do
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source ./$t.tcl > $t.log 2>&1
  grep -q "DONE_$t" $t.log && echo "OK $t" || { echo "FAIL $t"; grep ERROR $t.log | head -3; }
done
tar czf /tmp/shift_out.tgz *.bit 2>/dev/null; echo TAR_DONE